The standard offline technique: each edge exists on a contiguous set of time steps `[start, end)`, so an edge is *alive* at exactly the leaves covered by that interval on a segment tree over time. We push each interval's edge onto the O(log Q) tree nodes that fully cover it, then DFS the tree; at each node we union all its edges into a **rollback-capable DSU** (union-by-size, *no* path compression, history stack), answer queries at leaves with current component sizes, and roll back on the way up. Total work is O((V + E) log Q).

Three hazards handled without corrupting the DSU:
- **Delete of never-inserted edge** → per-edge multiplicity stack; popping an empty stack is a no-op.
- **Parallel edges** → edge key `u*V+v` (normalized `u≤v`) holds a *stack of insertion times*; each copy gets its own interval, overlapping copies simply union redundantly (harmless).
- **Self-loops** → skipped entirely (never affect connectivity, and union `find(v)==find(v)` would be a no-op anyway).

```js
class RollbackDSU {
  constructor(n) {
    this.parent = new Int32Array(n); this.sz = new Int32Array(n);
    for (let i = 0; i < n; i++) { this.parent[i] = i; this.sz[i] = 1; }
    this.history = []; // flat triples [rootA, childB, sizeB]
  }
  find(x) { while (this.parent[x] !== x) x = this.parent[x]; return x; }
  union(a, b) {
    a = this.find(a); b = this.find(b);
    if (a === b) return false;                 // parallel edge: no-op
    if (this.sz[a] < this.sz[b]) { const t = a; a = b; b = t; }
    this.parent[b] = a;
    this.history.push(a, b, this.sz[b]);
    this.sz[a] += this.sz[b];
    return true;
  }
  snapshot() { return this.history.length; }
  rollback(snap) {
    const h = this.history;
    while (h.length > snap) {
      const szB = h.pop(), b = h.pop(), a = h.pop();
      this.parent[b] = b; this.sz[a] -= szB; this.sz[b] = szB;
    }
  }
}

function solve(V, Q, ops, initialEdges = []) {
  if (Q === 0) return [];
  const edgeU = [], edgeV = [];
  const tree = new Array(4 * Q).fill(null);

  const addInterval = (node, l, r, ql, qr, eid) => {
    if (qr <= l || r <= ql) return;
    if (ql <= l && r <= qr) {
      (tree[node] ??= []).push(eid);
      return;
    }
    const mid = (l + r) >> 1;
    addInterval(node << 1, l, mid, ql, qr, eid);
    addInterval((node << 1) | 1, mid, r, ql, qr, eid);
  };

  // 1) initial graph: every copy alive from t=0
  const active = new Map(); // key u*V+v -> stack of insertion times
  for (const [u0, v0] of initialEdges) {
    if (u0 === v0) continue;
    const u = Math.min(u0, v0), v = Math.max(u0, v0);
    (active.get(u * V + v) ?? active.set(u * V + v, []).get(u * V + v)).push(0);
  }

  // 2) scan ops -> existence intervals [start, t)
  for (let t = 0; t < Q; t++) {
    const [type, a, b] = ops[t];
    if (type === 'query' || type === 'size') continue;
    let u = a, v = b;
    if (u === v) continue;                       // self loop: ignore
    if (u > v) [u, v] = [v, u];
    const key = u * V + v;
    const st = active.get(key);
    if (type === 'add') {
      if (st === undefined) active.set(key, [t]); else st.push(t);
    } else if (st !== undefined && st.length > 0) {
      const start = st.pop();                    // delete of absent edge: no-op
      const eid = edgeU.length;
      edgeU.push(u); edgeV.push(v);
      addInterval(1, 0, Q, start, t, eid);
    }
  }
  // 3) flush edges still present at the end
  for (const [key, st] of active)
    for (const start of st) {
      const eid = edgeU.length;
      edgeU.push(Math.floor(key / V), 0);        // placeholder; fixed below
      edgeV.push(key % V, 0);
      edgeU[eid] = Math.floor(key / V); edgeV[eid] = key % V;
      addInterval(1, 0, Q, start, Q, eid);
    }

  // 4) DFS over time tree, answer leaves, rollback on exit
  const dsu = new RollbackDSU(V);
  const results = [];
  const dfs = (node, l, r) => {
    const snap = dsu.snapshot();
    const list = tree[node];
    if (list) for (const eid of list) dsu.union(edgeU[eid], edgeV[eid]);
    if (r - l === 1) {
      const op = ops[l];
      if (op[0] === 'query') {
        const ru = dsu.find(op[1]), rv = dsu.find(op[2]);
        results.push({ connected: ru === rv, size: dsu.sz[ru] });
      } else if (op[0] === 'size') {
        results.push({ size: dsu.sz[dsu.find(op[1])] });
      }
    } else {
      const mid = (l + r) >> 1;
      dfs(node << 1, l, mid);
      dfs((node << 1) | 1, mid, r);
    }
    dsu.rollback(snap);
  };
  dfs(1, 0, Q);
  return results;
}
```

